"""1623 (#115): Record-MissionCoverage-v1612.ps1 with -FarReachBody, a body pull with the body in line of sight. The lab
body harness (Test-CarryBody 1427-1442, 1621, 1622) put Emily face to a cabinet, so its "refused" pulls never had the
body under the reticle (1622a film). After a verified client choke of the takedown target, Emily gets the pull upgrades
and Far Reach and tries up to eight spots 4.5 m from the body (behind it along the approach line first, then around it),
facing the body at about 18 degrees down. At each spot she holds the aim 1.4 s while the harness reads the aimed handle
(arkCpntPowerGrapple +0xdc through UsePower 63 +0x60); the release casts. A spot whose aim held the body's handle is the
pull: the harness then samples for 7 s the player states, the aimed and pulled handles (GrabGrappledEntity 84 +0x38), the
body's position in both worlds and its NPC entries in both streams. With -FarReachRelease the client's NPC stream is off
during the tries (control). Both windows are filmed for the whole search. Generated by make_mission_coverage_v1623.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-MissionCoverage-v1612.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
lines = s.split('\n')
lines.insert(1, "# 1623 (#115): -FarReachBody pulls the choked body with Far Reach from a spot in line of sight. Generated by make_mission_coverage_v1623.py.")
s = '\n'.join(lines)
first = s.index('\n')
assert s[:first].rstrip().endswith(')')
s = s[:first].rstrip()[:-1] + ',[switch]$FarReachBody,[switch]$FarReachRelease)' + s[first:]
block = r'''
     if($FarReachBody-and$TakedownKind-eq'choke'-and$source-eq'client'){
      # 1623 (#115): Far Reach at the choked body from a spot with the body in line of sight.
      C $source 'coop_player_health_hold on'
      foreach($fbItem in 'components/characters/player/base/attributes/grapple_pull_objects.inventoryitem','components/characters/player/base/attributes/grapple_pull_npcs.inventoryitem','models/powers/grapple/grapple.inventoryitem'){C $source "coop_grant_named $fbItem";Start-Sleep -Milliseconds 900}
      Start-Sleep -Milliseconds 1200;$row.farReachGrant=try{(S $source '.observer-camera.json').itemGrant.named.result}catch{$null}
      $fbBody={param($fbRole)$fbN=@((Q $fbRole '--world-npcs').npcs|Where-Object spawnerName -eq $TargetSpawner);if($fbN.Count){$fbN[0]}else{$null}}
      $fbAim={$fbPs=try{Q $source '--player-states'}catch{$null};if(!$fbPs){return $null};$fbOut=[ordered]@{active=@($fbPs.active|ForEach-Object {$_.id});aim=$null;pulled=$null}
       foreach($fbId in 63,84){if(!@($fbPs.active|Where-Object {$_.id-eq$fbId}).Count){continue}
        $fbSlot='0x{0:x}' -f ([Convert]::ToUInt64(($fbPs.mode-replace'^0x',''),16)+0x10+$fbId*8);$fbState=try{(Q $source '--object' $fbSlot).words[0].word}catch{$null};if(!$fbState){continue}
        $fbWords=try{(Q $source '--object' $fbState).words}catch{$null};if(!$fbWords){continue}
        if($fbId-eq84){$fbWord=@($fbWords|Where-Object {$_.offset-eq'0x38'});if($fbWord.Count){$fbOut.pulled='0x{0:x}' -f ([Convert]::ToUInt64(($fbWord[0].word-replace'^0x',''),16)-band[uint64]4294967295)}}
        else{$fbPw=@($fbWords|Where-Object {$_.offset-eq'0x60'-and$_.pointerType-eq'.?AVarkCpntPowerGrapple@@'});if($fbPw.Count){$fbWord=@($(try{(Q $source '--object' $fbPw[0].word).words}catch{@()})|Where-Object {$_.offset-eq'0xd8'})
         if($fbWord.Count){$fbOut.aim='0x{0:x}' -f ([Convert]::ToUInt64(($fbWord[0].word-replace'^0x',''),16)-shr 32)}}}}
       [pscustomobject]$fbOut}
      $fbEntry={param($fbRole,$fbH)$fbE=@($(try{(S $fbRole '.npc-stream.json').entries}catch{@()})|Where-Object {$fbH-and('0x{0:x}' -f [uint32]$_.handle)-eq$fbH})
       if($fbE.Count){[pscustomobject]@{result=$fbE[0].result;unconscious=$fbE[0].unconscious;ready=$fbE[0].ready;poses=$fbE[0].poses}}else{$null}}
      $fbB=& $fbBody $source;$fbHb=& $fbBody host;if(!$fbB){throw 'Far Reach body: no body in the source world'}
      $fbHandle=[string]$fbB.handle;$fbHostHandle=if($fbHb){[string]$fbHb.handle}else{$null};$fbX=[double]$fbB.position[0];$fbY=[double]$fbB.position[1];$fbZ=[double]$fbB.position[2]
      $row.farReach=[ordered]@{body=$fbB.position;handle=$fbHandle;hostBody=$(if($fbHb){$fbHb.position}else{$null});hostHandle=$fbHostHandle;spots=@();chosen=$null;released=[bool]$FarReachRelease}
      if($FarReachRelease){C $source 'coop_product_auto off';C $source 'coop_npc_stream off';Start-Sleep -Milliseconds 2500;$row.farReach.releasedEntry=& $fbEntry $source $fbHandle}
      $fbFilms=Capture "$key-farreach" 75;$fbPitch=[Math]::Atan2(1.45,4.5)*180/[Math]::PI;$fbPull=[Collections.Generic.List[object]]::new()
      foreach($fbOff in 180,135,225,90,270,45,315,0){$fbD=($syaw+$fbOff)*[Math]::PI/180;$fbPx=$fbX+4.5*[Math]::Cos($fbD);$fbPy=$fbY+4.5*[Math]::Sin($fbD);$fbYaw=[Math]::Atan2($fbY-$fbPy,$fbX-$fbPx)*180/[Math]::PI
       C $source (P $fbPx $fbPy ($fbZ+1.7) $fbYaw);Start-Sleep -Milliseconds 600;try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch $fbPitch -Quick|Out-Null}catch{}
       $fbLt=Start-Process (Get-Process -Id $PID).Path -ArgumentList @('-NoProfile','-File',"$lab/Send-D2Input.ps1",'-Role',$source,'-LeftTrigger','255','-DurationMs','1400') -WindowStyle Hidden -PassThru
       $fbSeen=@();$fbW=[Diagnostics.Stopwatch]::StartNew();while($fbW.ElapsedMilliseconds-lt1350){$fbA=& $fbAim;if($fbA-and$fbA.aim){$fbSeen+=$fbA.aim};Start-Sleep -Milliseconds 40}
       $fbHit=@($fbSeen|Where-Object {$_-eq$fbHandle}).Count
       $row.farReach.spots+=[pscustomobject]@{offset=$fbOff;at=@($fbPx,$fbPy);yaw=$fbYaw;aimed=@($fbSeen|Select-Object -Unique);hit=$fbHit}
       if($fbHit){$row.farReach.chosen=$fbOff;$fbW=[Diagnostics.Stopwatch]::StartNew()
        while($fbW.ElapsedMilliseconds-lt7000){$fbA=& $fbAim;$fbSb=& $fbBody $source;$fbHb2=& $fbBody host
         $fbPull.Add([pscustomobject]@{ms=$fbW.ElapsedMilliseconds;target=$fbA;source=$(if($fbSb){$fbSb.position}else{$null});host=$(if($fbHb2){$fbHb2.position}else{$null});sourceEntry=$(& $fbEntry $source $fbHandle);hostEntry=$(& $fbEntry host $fbHostHandle)});Start-Sleep -Milliseconds 40}
        try{$fbLt.WaitForExit(3000)|Out-Null}catch{};break}
       try{$fbLt.WaitForExit(4000)|Out-Null}catch{};Start-Sleep -Milliseconds 1500}
      Save "$out/$key-farreach-pull.json" @($fbPull);Save "$out/$key-farreach-spots.json" @($row.farReach.spots)
      if($FarReachRelease){C $source 'coop_npc_stream on';C $source 'coop_product_auto on';Start-Sleep -Milliseconds 1500}
      $fbEnd=[ordered]@{source=$(& $fbBody $source);host=$(& $fbBody host)};$row.farReach.end=[ordered]@{source=$(if($fbEnd.source){$fbEnd.source.position}else{$null});host=$(if($fbEnd.host){$fbEnd.host.position}else{$null})}
      $fbPulled=@($fbPull|ForEach-Object {$_.target.pulled}|Where-Object {$_}|Select-Object -Unique);$fbStates=@($fbPull|ForEach-Object {$_.target.active}|Where-Object {$null-ne$_}|ForEach-Object {[int]$_}|Sort-Object -Unique)
      $row.farReach.pulled=$fbPulled;$row.farReach.states=$fbStates
      $fbMoved={param($a,$b)if(!$a-or!$b){return $null};[Math]::Round([Math]::Sqrt(([double]$a[0]-$b[0])*([double]$a[0]-$b[0])+([double]$a[1]-$b[1])*([double]$a[1]-$b[1])+([double]$a[2]-$b[2])*([double]$a[2]-$b[2])),2)}
      $row.farReach.sourceMoved=& $fbMoved $fbB.position $row.farReach.end.source;$row.farReach.hostMoved=& $fbMoved $row.farReach.hostBody $row.farReach.end.host
      foreach($fbC in $fbFilms){try{if(!$fbC.WaitForExit(80000)){Stop-Process -Id $fbC.Id}}catch{}}
      C $source 'coop_player_health_hold off'
      $row.checks.Add("Far Reach body: spots $(@($row.farReach.spots|ForEach-Object {"$($_.offset):$(@($_.aimed)-join '/')"})-join ' '); chosen $($row.farReach.chosen); pulled $($fbPulled-join ','); states $($fbStates-join ','); body moved source $($row.farReach.sourceMoved) m, host $($row.farReach.hostMoved) m")}'''
anchor = '     $row.checks.Add("Native $TakedownKind of $($tg[0].definition): source states $($row.sourceStates-join \',\'); $expected in both worlds")}}'
rep(anchor, anchor[:-2] + block + '}}')
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-MissionCoverage-v1623.ps1').write_bytes(out.encode('utf-8'))
print('ok')
